import pkg from '../package.json' with { type: 'json' };
import { fileURLToPath } from 'node:url';
import type { StorybookConfig } from '@storybook/react-vite';

const root = path.dirname(fileURLToPath(import.meta.url));

const config: StorybookConfig = {
  stories: [
    '../features/**/*.stories.@(ts|tsx)',
    '../shared/**/*.stories.@(ts|tsx)',
    './stories/**/*.stories.@(ts|tsx)',
  ],
  addons: ['@storybook/addon-a11y'],
  framework: {
    name: '@storybook/react-vite',
    options: {},
  },
  async viteFinal(viteConfig) {
    // RN Primitives publish JSX in .js/.mjs; Vite otherwise parses these as JS.
    viteConfig.plugins ??= [];
    viteConfig.plugins.push({
      name: 'rn-primitives-jsx', enforce: 'pre',
      transform(code, id) {
        // Expo emits value imports in this declarations-only module.
        if (id.endsWith('/expo-modules-core/build/ts-declarations/global.js')) return { code: 'export {};' };
        if (id.endsWith('/features/ai/ui/provider-icon.tsx')) {
          const assets: string[] = [];
          const transformed = code.replace(/require\((['"])([^'"]+\.png)\1\)/g, (_match, _quote, asset: string) => {
            const name = `providerIcon${assets.length}`;
            assets.push(`import ${name} from '${asset}';`);
            return name;
          });
          return { code: `${assets.join('\n')}\n${transformed}` };
        }
        if (/node_modules\/@rn-primitives\/.*\.[cm]?js$/.test(id)) return transformWithOxc(code, id, { lang: 'tsx', jsx: { runtime: 'automatic' } });
      },
    });
    viteConfig.optimizeDeps ??= {};
    viteConfig.optimizeDeps.exclude = [...(viteConfig.optimizeDeps.exclude ?? []), ...Object.keys(pkg.dependencies).filter((name) => name.startsWith('@rn-primitives/'))];
    viteConfig.plugins = [...(viteConfig.plugins ?? []), tailwindcss(), uniwind({ cssEntryFile: './global.css', dtsFile: './uniwind-types.d.ts' })];
    viteConfig.resolve ??= {};
    const existing = viteConfig.resolve.alias;
    const aliases = Array.isArray(existing)
      ? existing
      : Object.entries(existing ?? {}).map(([find, replacement]) => ({ find, replacement }));
    viteConfig.resolve.alias = [
      { find: /^react-native$/, replacement: 'react-native-web' },
      { find: 'react-native-svg', replacement: path.resolve(root, '../node_modules/react-native-svg/lib/module/ReactNativeSVG.web.js') },
      { find: /^\.\.\/fabric\/NativeSvgSoundModule$/, replacement: path.resolve(root, 'stubs/native-svg-sound-module.js') },
      { find: '@react-native/assets-registry/registry', replacement: path.resolve(root, 'stubs/assets-registry.js') },
      { find: /^@expo\/vector-icons\/MaterialCommunityIcons$/, replacement: path.resolve(root, 'stubs/vector-icons.tsx') },
      { find: /^@expo\/vector-icons$/, replacement: path.resolve(root, 'stubs/vector-icons.tsx') },
      { find: /^@\//, replacement: `${path.resolve(root, '..')}/` },
      ...aliases,
    ];
    viteConfig.resolve.dedupe = ['react', 'react-dom', 'react-native-web'];
    viteConfig.resolve.extensions = [
      '.web.tsx',
      '.web.ts',
      '.web.jsx',
      '.web.mjs',
      '.web.js',
      ...(viteConfig.resolve.extensions ?? []),
    ];
    viteConfig.define = {
      ...viteConfig.define,
      __DEV__: JSON.stringify(true),
      global: 'globalThis',
    };
    return viteConfig;
  },
};

